package com.example.shop.w2;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
public class Piece {
    @Id
    Long id;
    String sku;
}

package com.example.shop.w2;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.OneToMany;
import jakarta.persistence.MapKey;

@Entity
public class Shelf {
    @Id
    private Long id;
    @OneToMany
    @MapKey(name = "nope")
    private java.util.Map<String, Piece> pieces;
}
